// The watcher mod, registered from hooks/watch/watcher.ts: the farm-out runs and work rounds THIS session launched, read from files only.
//
//   status line   one compact line while anything runs; cleared when nothing does
//   wake          $.prompt.submit ONCE per run that reaches DONE or GONE, remembered in $.store
//   /farm         a table of this session's runs, printed at once, no turn
//   beacon        <TMPDIR>/farm-events/<session>/watcher.alive, rewritten by every tick that completes:
//                 the one thing outside this module that can tell a session whose mods never loaded
//
// It replaces the farm-runs plugin monitor, which never re-armed once it stopped. A timer started
// in session.start comes back with every reload. A headless session (`claude -p`, the SDK, a farm
// child with FARM_OUT_CHILD=1) registers nothing: it has nobody to draw for, and a farm child
// waking itself about its own runs would loop.
import type { EngineInterface, On } from 'claude-code'
import {
  BEACON, classify, parseEvents, statusLine, table, TICK_MS, pastHorizon, wakeable, wakeText, waitText, workPhase, workRound,
  type Facts, type Run, type View,
} from './runs.ts'
import { setForecastCache } from '../jev/forecast-mod.ts'

// The Jev forecast band's sampling tick (hooks/jev/forecast-mod.ts): ten minutes, and the script's
// own hourly gate decides whether that reaches the network.
const FORECAST_TICK_MS = 10 * 60_000

// Notified keys older than this are pruned from the shared store.
const KEEP_NOTIFIED_MS = 7 * 24 * 3600_000

// Module state: lost on reload by design. The store holds what must survive one.
const sessions = new Set<string>()
const firstSeen = new Map<string, number>()
const cache = new Map<string, { mtimeMs: number; size: number; runs: Run[] }>()
const woke = new Set<string>()
let lastStatus: string | undefined
let ticking = false

async function tmpRoot($: EngineInterface): Promise<string> {
  return ((await $.env.get('TMPDIR')) || '/tmp').replace(/\/+$/, '')
}

async function eventDirs($: EngineInterface): Promise<string[]> {
  const sid = await $.session.id()
  if (sid) sessions.add(sid)
  const roots = [...new Set([await tmpRoot($), '/tmp'])]
  const dirs: string[] = []
  for (const root of roots) for (const s of sessions) dirs.push(`${root.replace(/\/+$/, '')}/farm-events/${s}`)
  return dirs
}

async function readRuns($: EngineInterface, nowMs: number): Promise<Run[]> {
  const runs: Run[] = []
  for (const dir of await eventDirs($)) {
    let entries: Awaited<ReturnType<EngineInterface['fs']['list']>>
    try { entries = await $.fs.list(dir) } catch { continue }
    const sid = dir.split('/').pop() ?? ''
    for (const ent of entries) {
      const m = /^(\d+)\.ndjson$/.exec(ent.name)
      if (!m || ent.kind !== 'file') continue
      const file = `${dir}/${ent.name}`
      if (!firstSeen.has(file)) firstSeen.set(file, Math.min(nowMs, ent.mtimeMs || nowMs))
      const hit = cache.get(file)
      if (hit && hit.mtimeMs === ent.mtimeMs && hit.size === ent.size) { runs.push(...hit.runs); continue }
      let text = ''
      try { text = await $.fs.read(file) } catch { continue }
      const parsed = parseEvents(text, file, Number(m[1]), sid)
      for (const r of parsed) r.fileMtimeMs = ent.mtimeMs
      cache.set(file, { mtimeMs: ent.mtimeMs, size: ent.size, runs: parsed })
      runs.push(...parsed)
    }
  }
  return runs
}

async function nonEmpty($: EngineInterface, p: string): Promise<boolean> {
  try { return (await $.fs.stat(p)).size > 0 } catch { return false }
}

async function readText($: EngineInterface, p: string): Promise<string | undefined> {
  try { return await $.fs.read(p) } catch { return undefined }
}

/** Everything classify() needs, gathered with one ps call and a stat per artifact. */
async function gather($: EngineInterface, runs: Run[]): Promise<Facts> {
  const facts: Facts = {
    alive: new Set(), present: new Set(), firstSeen, loopExit: new Map(), loopExitAt: new Map(), round: new Map(), phase: new Map(),
  }
  const open = [...new Set(runs.filter(r => !r.done).map(r => r.pid))]
  if (open.length) {
    try {
      const ps = await $.process.run(['ps', '-o', 'pid=', '-p', open.join(',')], { timeoutMs: 5000 })
      for (const tok of ps.stdout.split(/\s+/)) if (/^\d+$/.test(tok)) facts.alive.add(Number(tok))
    } catch {
      // ps unavailable: claim every open run alive rather than wake the session with false GONEs.
      for (const p of open) facts.alive.add(p)
    }
  }
  const paths = new Set<string>()
  const workDirs = new Set<string>()
  for (const r of runs) {
    for (const p of [r.out, ...r.claims]) if (p && p.startsWith('/')) paths.add(p)
    if ((r.label === 'work-round' || r.label === 'work-loop') && r.out) workDirs.add(r.out.replace(/\/[^/]*$/, ''))
  }
  for (const p of paths) if (await nonEmpty($, p)) facts.present.add(p)
  for (const d of workDirs) {
    const exit = await readText($, `${d}/loop.exit`)
    if (exit !== undefined && exit.trim() !== '') {
      facts.loopExit.set(`${d}/loop.exit`, exit.trim())
      try { facts.loopExitAt!.set(`${d}/loop.exit`, (await $.fs.stat(`${d}/loop.exit`)).mtimeMs) } catch {}
    }
    const loopLog = await readText($, `${d}/loop.log`)
    const round = loopLog && workRound(loopLog)
    if (round) facts.round.set(d, round)
    // Round N>1 logs to run-<HHMMSS>.log; the newest run*.log is the live round's.
    let log = `${d}/run.log`
    try {
      const logs = (await $.fs.list(d)).filter((e) => /^run.*\.log$/.test(e.name))
      logs.sort((a, b) => b.mtimeMs - a.mtimeMs)
      if (logs[0]) log = `${d}/${logs[0].name}`
    } catch {}
    const runLog = await readText($, log)
    const phase = runLog && workPhase(runLog)
    if (phase) facts.phase.set(d, phase)
  }
  return facts
}

async function snapshot($: EngineInterface): Promise<{ views: View[]; nowMs: number }> {
  const nowMs = await $.clock.now()
  const runs = await readRuns($, nowMs)
  return { views: classify(runs, await gather($, runs)), nowMs }
}

async function wake($: EngineInterface, views: View[], nowMs: number) {
  for (const v of wakeable(views)) {
    // A live run's newest WAIT alert wakes once per waits value: the run stays running.
    if (v.state === 'running' && v.wait) {
      const wid = `${v.id}:wait:${v.wait.waits}`
      if (!woke.has(wid)) {
        woke.add(wid)
        const wkey = `notified:${wid}`
        if (!(await $.store.get(wkey)) && !pastHorizon(v, nowMs)) {
          await $.store.set(wkey, nowMs)
          void $.prompt.submit({ text: waitText(v) })
        }
      }
      continue
    }
    if (v.state === 'running' || woke.has(v.id)) continue
    woke.add(v.id)
    const key = `notified:${v.id}`
    if (await $.store.get(key)) continue
    if (pastHorizon(v, nowMs)) continue
    // Recorded BEFORE the submit: a reload between the two must not wake twice.
    await $.store.set(key, nowMs)
    // Never awaited: submit resolves when the turn starts, and this tick may run mid-turn.
    void $.prompt.submit({ text: wakeText(v, nowMs) })
  }
}

async function prune($: EngineInterface, nowMs: number) {
  for (const k of await $.store.keys()) {
    if (!k.startsWith('notified:')) continue
    const at = Number(await $.store.get(k))
    if (!(nowMs - at < KEEP_NOTIFIED_MS)) await $.store.delete(k)
  }
}

async function tick($: EngineInterface) {
  if (ticking) return
  ticking = true
  try {
    const { views, nowMs } = await snapshot($)
    const line = statusLine(views, nowMs)
    if (line !== lastStatus) {
      lastStatus = line
      $.ui.status(line)
    }
    await wake($, views, nowMs)
    // Last, so a tick that throws leaves the beacon to go stale. write() creates the directory, so
    // the beacon is there before this session's first run files itself.
    const sid = await $.session.id()
    if (sid) await $.fs.write(`${await tmpRoot($)}/farm-events/${sid}/${BEACON}`, String(Math.floor(nowMs / 1000)))
  } finally {
    ticking = false
  }
}

/** One forecast sample, under credit-warn's hourly gate, then the cache handed to the band. */
async function forecastTick($: EngineInterface): Promise<void> {
  try {
    await $.process.run(['bun', `${$.plugin.root}/scripts/lib/openrouter-credits.ts`, '--sample'], { timeoutMs: 20_000 })
  } catch { /* the read below still shows the last sample */ }
  let c: unknown = null
  try { c = JSON.parse(await $.fs.read(`${await tmpRoot($)}/openrouter-credits.json`)) } catch { /* no cache yet */ }
  setForecastCache(c)
  try { $.ui.invalidate('ui.render') } catch { /* headless */ }
}

export function registerWatcher(on: On) {
  on('session.start', async ($, e, next) => {
    if (!e.isInteractive || (await $.env.get('FARM_OUT_CHILD')) === '1') return next(e)
    // The promise is returned so a test clock can settle on it; the engine does not wait on it.
    $.clock.every(TICK_MS, () => tick($))
    void tick($)
    void prune($, await $.clock.now())
    // The module's one session.start, so the Jev forecast band's tick starts here too.
    $.clock.every(FORECAST_TICK_MS, () => forecastTick($))
    void forecastTick($)
    await $.command.register({
      name: 'farm',
      description: "This session's farm-out runs and work rounds: state, elapsed, artifact, report",
      immediate: true,
    })
    return next(e)
  })

  on('command.run', { command: 'farm' }, async ($) => {
    const { views, nowMs } = await snapshot($)
    return { text: table(views, nowMs) }
  })
}

files.hooks/guards/core.ts:
// The plugin's tool-call guards, written once for two hosts: the settings-hook scripts in hooks/
// (bun, node fs, stdin/stdout) and the mod (hooks/guards/mod.ts, $.fs/$.env). A hooks module runs
// with no Node, so nothing under hooks/guards/ may import node:* except node-io.ts, which only the
// scripts load. Every guard is `(payload, io) => Promise<Outcome>` over the settings-hook payload.

/** The settings-hook stdin payload, as Claude Code sends it (PreToolUse / PostToolUse). */
export type Payload = Record<string, unknown>

/** A guard's answer. Neither field: no opinion. There is no allow — silence is the pass. */
export interface Outcome {
  deny?: string
  context?: string
}

export interface FileStat {
  kind: 'file' | 'dir' | 'other'
  size: number
  mtimeMs: number
}

/** The guard's whole view of the world. Relative paths resolve against `cwd`. */
export interface GuardIO {
  env: (name: EnvName) => string | undefined
  cwd: string
  pluginRoot: string
  /** node's os.tmpdir(): TMPDIR, TMP, TEMP, then /tmp. */
  osTmpdir: string
  /** The script's process.ppid; the mod's session id. Only a last-resort counter key. */
  fallbackKey: string
  nowMs: () => number
  stat: (p: string) => Promise<FileStat | null>
  read: (p: string) => Promise<string | null>
  list: (p: string) => Promise<string[] | null>
  write: (p: string, text: string) => Promise<void>
  append: (p: string, text: string) => Promise<void>
}

/** Every variable a guard reads. The mod reads each by literal name (validate requires it). */
export const ENV_NAMES = [
  'LOOK_AT_NESTED',
  'READ_GUARD_BYTES',
  'COMPACT_THRESHOLD',
  'COMPACT_INTERVAL',
  'CLAUDE_CODE_SESSION_ID',
  'TMPDIR',
  'TEMP',
  'TMP',
  'WORK_ALLOW_CRON_DELETE',
] as const
export type EnvName = (typeof ENV_NAMES)[number]

export type Guard = (payload: Payload, io: GuardIO) => Promise<Outcome>

/** `path.join(a, b)` for the shapes guards build: collapses duplicate slashes. */
export function joinPath(...parts: string[]): string {
  return parts.filter(p => p !== '').join('/').replace(/\/{2,}/g, '/')
}

/** Absolute form of `p` against `cwd`, the way the scripts' relative fs calls resolve. */
export function absolute(cwd: string, p: string): string {
  return p.startsWith('/') ? p : joinPath(cwd, p)
}

/** The deny a PreToolUse gate gives when it throws: the same text `denyOnCrash` prints. */
export function crashDeny(gate: string, kind: string, error: unknown): string {
  let detail: string
  try {
    detail = error instanceof Error ? `${error.name}: ${error.message}` : String(error)
  } catch {
    detail = 'an unrepresentable value was thrown'
  }
  return (
    `${gate}: this gate crashed (${kind}: ${detail}) and could not decide. A gate that cannot ` +
    `resolve identity or policy denies; a non-zero exit would have been treated as non-blocking ` +
    `and silently permitted this call. Re-run after fixing the underlying fault.`
  )
}

